Algorithm Tip
  Define bill As Integer;
  Define friends As Integer;
  Read bill;
  Read friends;
  If friends = 0 Then
    Write "Nobody is there to pay";
  Else
    Write "Each one pays: ", ceil((bill + bill Div 10) / friends);
  EndIf
EndAlgorithm

