Subroutine TotalWithTip(bill As Integer) As Integer
  Return bill + bill Div 10;
EndSubroutine

Subroutine ShareOfEach(total As Integer, friends As Integer) As Integer
  Return ceil(total / friends);
EndSubroutine

Algorithm Tip
  Define bill As Integer;
  Define friends As Integer;
  Read bill;
  Read friends;
  If friends = 0 Then
    Write "Nobody is there to pay";
  Else
    Write "Each one pays: ", ShareOfEach(TotalWithTip(bill), friends);
  EndIf
EndAlgorithm
